    # Data rows start at 7
    r = 7
    for row in results:
        out = dict(row)
        out["Projected_Stockout_Date"] = _iso_or_none(out["Projected_Stockout_Date"])
        out["Required_Delivery_Date"] = _iso_or_none(out["Required_Delivery_Date"])
        out["Earliest_Scheduled_Delivery_Date"] = _iso_or_none(out["Earliest_Scheduled_Delivery_Date"])

        for c, h in enumerate(headers, start=1):
            v = out.get(h)
            if v is None:
                continue
            ws1.cell(r, c).value = v
        r += 1

    # Sheet 2
    headers2 = [
        "Part_Code",
        "Required_Delivery_Date",
        "Crates_Required_Rounded_Up",
        "Additional_Units_Needed",
        "Rounding_Applied",
        "Earlier_Delivery_Required",
    ]
    for c, h in enumerate(headers2, start=1):
        ws2.cell(1, c).value = h

    r2 = 2
    for row in results:
        if int(row["Crates_Required_Rounded_Up"]) <= 0:
            continue

        required_iso = _iso_or_none(row["Required_Delivery_Date"])

        values = {
            "Part_Code": row["Part_Code"],
            "Required_Delivery_Date": required_iso,
            "Crates_Required_Rounded_Up": int(row["Crates_Required_Rounded_Up"]),
