import math
from dataclasses import dataclass
from datetime import date, datetime, timedelta
from typing import Dict, List, Optional, Tuple, Union

import openpyxl

SOURCE_PATH = "/root/Maintenance_Parts_and_Deliveries_Latest.xlsx"
OUT_PATH = "/root/maintenance_resupply_actions_sep_2025.xlsx"


def _parse_date(v) -> Optional[date]:
    """Parse dates that may come as Excel datetime/date or ISO-like strings."""
    if v is None or v == "":
        return None
    if isinstance(v, date) and not isinstance(v, datetime):
        return v
    if isinstance(v, datetime):
        return v.date()
    if isinstance(v, str):
        s = v.strip()
        # Expect formats like YYYY-MM-DD
        try:
            return datetime.strptime(s, "%Y-%m-%d").date()
        except ValueError:
            # Try a couple common alternatives just in case
            for fmt in ("%m/%d/%Y", "%Y/%m/%d", "%d-%b-%Y"):
                try:
                    return datetime.strptime(s, fmt).date()
                except ValueError:
                    pass
        raise ValueError(f"Unrecognized date string: {v!r}")

    raise TypeError(f"Unrecognized date value type: {type(v)} ({v!r})")


@dataclass(frozen=True)
class PartRow:
    part_code: str
    current_units: float
    daily_consumption_units: float


@dataclass(frozen=True)
class DeliveryRow:
    part_code: str
    inbound_date: date
    inbound_units: float


def _find_header_map(row_values: List[object]) -> Dict[str, int]:
    """Return mapping of normalized header -> 1-based column index."""
    m: Dict[str, int] = {}
    for idx, v in enumerate(row_values, start=1):
        if v is None:
            continue
        if isinstance(v, str):
            key = v.strip().lower().replace(" ", "_")
            m[key] = idx
    return m


