import math
from dataclasses import dataclass
from datetime import date, datetime, timedelta
from typing import Dict, List, Optional, Tuple, Union

import openpyxl

SOURCE_PATH = "/root/Maintenance_Parts_and_Deliveries_Latest.xlsx"
OUT_PATH = "/root/maintenance_resupply_actions_sep_2025.xlsx"


def _parse_date(v) -> Optional[date]:
    """Parse dates that may come as Excel datetime/date or ISO-like strings."""
    if v is None or v == "":
        return None
    if isinstance(v, date) and not isinstance(v, datetime):
        return v
    if isinstance(v, datetime):
        return v.date()
    if isinstance(v, str):
        s = v.strip()
        # Expect formats like YYYY-MM-DD
        try:
            return datetime.strptime(s, "%Y-%m-%d").date()
        except ValueError:
            # Try a couple common alternatives just in case
            for fmt in ("%m/%d/%Y", "%Y/%m/%d", "%d-%b-%Y"):
                try:
                    return datetime.strptime(s, fmt).date()
                except ValueError:
                    pass
        raise ValueError(f"Unrecognized date string: {v!r}")

    raise TypeError(f"Unrecognized date value type: {type(v)} ({v!r})")


@dataclass(frozen=True)
class PartRow:
    part_code: str
    current_units: float
    daily_consumption_units: float


@dataclass(frozen=True)
class DeliveryRow:
    part_code: str
    inbound_date: date
    inbound_units: float


def _find_header_map(row_values: List[object]) -> Dict[str, int]:
    """Return mapping of normalized header -> 1-based column index."""
    m: Dict[str, int] = {}
    for idx, v in enumerate(row_values, start=1):
        if v is None:
            continue
        if isinstance(v, str):
            key = v.strip().lower().replace(" ", "_")
            m[key] = idx
    return m


def read_source() -> Tuple[date, date, int, List[PartRow], List[DeliveryRow], Union[float, Dict[str, float]]]:
    wb = openpyxl.load_workbook(SOURCE_PATH, data_only=False)

    ws_parts = wb["Current Parts"]
    ws_deliv = wb["Scheduled Deliveries"]
    ws_ratio = wb["Ratio"]

    as_of = _parse_date(ws_parts["B1"].value)
    horizon_end = _parse_date(ws_parts["D1"].value)
    if as_of is None or horizon_end is None:
        raise ValueError(f"Missing AsOfDate or PlanningHorizonEnd: B1={ws_parts['B1'].value!r}, D1={ws_parts['D1'].value!r}")

    remaining_days = (horizon_end - as_of).days

    # Current Parts: find header row (contains 'part_code')
    header_row_idx = None
    header_map: Dict[str, int] = {}
    for r in range(1, min(ws_parts.max_row, 50) + 1):
        vals = [ws_parts.cell(r, c).value for c in range(1, ws_parts.max_column + 1)]
        m = _find_header_map(vals)
        if "part_code" in m and "current_units" in m and "daily_consumption_units" in m:
            header_row_idx = r
            header_map = m
            break
    if header_row_idx is None:
        raise ValueError("Could not locate Current Parts header row with expected columns")

    parts: List[PartRow] = []
    for r in range(header_row_idx + 1, ws_parts.max_row + 1):
        part_code = ws_parts.cell(r, header_map["part_code"]).value
        if part_code is None or str(part_code).strip() == "":
            continue
        part_code = str(part_code).strip()
        current_units = ws_parts.cell(r, header_map["current_units"]).value
        daily = ws_parts.cell(r, header_map["daily_consumption_units"]).value

        if current_units is None or current_units == "":
            current_units = 0
        if daily is None or daily == "":
            daily = 0

        parts.append(
            PartRow(
                part_code=part_code,
                current_units=float(current_units),
                daily_consumption_units=float(daily),
            )
        )

    # Scheduled Deliveries
    deliv_header = [ws_deliv.cell(1, c).value for c in range(1, ws_deliv.max_column + 1)]
    deliv_map = _find_header_map(deliv_header)

    # Identify required columns
    # Observed: Part_Code, Delivery Date, Crates, Units
    part_col = deliv_map.get("part_code")
    date_col = deliv_map.get("delivery_date")
    units_col = deliv_map.get("units")

    if part_col is None or date_col is None or units_col is None:
        raise ValueError(f"Scheduled Deliveries header missing required columns. header={deliv_header!r}")

    deliveries: List[DeliveryRow] = []
    for r in range(2, ws_deliv.max_row + 1):
        p = ws_deliv.cell(r, part_col).value
        if p is None or str(p).strip() == "":
            continue
        p = str(p).strip()
        d = _parse_date(ws_deliv.cell(r, date_col).value)
        if d is None:
            continue
        units = ws_deliv.cell(r, units_col).value
        if units is None or units == "":
            units = 0
        deliveries.append(DeliveryRow(part_code=p, inbound_date=d, inbound_units=float(units)))

    # Ratio
    # Observed: header 'Units_Per_Crate' and a single value in A2
    ratio_value = None
    per_part_ratio: Dict[str, float] = {}

    # read all non-empty rows
    ratio_rows = []
    for r in range(1, ws_ratio.max_row + 1):
        row = [ws_ratio.cell(r, c).value for c in range(1, ws_ratio.max_column + 1)]
        if any(v is not None and v != "" for v in row):
            ratio_rows.append((r, row))

    if len(ratio_rows) == 2 and isinstance(ratio_rows[0][1][0], str) and "units" in ratio_rows[0][1][0].lower():
        ratio_value = ratio_rows[1][1][0]
        if ratio_value is None or ratio_value == "":
            raise ValueError("Ratio sheet had header but no ratio value")
        ratio_value = float(ratio_value)
        ratio: Union[float, Dict[str, float]] = ratio_value
    else:
        # Attempt per-part lookup: header row includes part_code and ratio
        header_r = ratio_rows[0][0]
        header_vals = [ws_ratio.cell(header_r, c).value for c in range(1, ws_ratio.max_column + 1)]
        m = _find_header_map(header_vals)
        pc = m.get("part_code")
        upc = m.get("units_per_crate")
        if pc is None or upc is None:
            raise ValueError("Unsupported Ratio sheet layout")

        for r in range(header_r + 1, ws_ratio.max_row + 1):
            part = ws_ratio.cell(r, pc).value
            if part is None or str(part).strip() == "":
                continue
            val = ws_ratio.cell(r, upc).value
            if val is None or val == "":
                continue
            per_part_ratio[str(part).strip()] = float(val)

        if not per_part_ratio:
            raise ValueError("Ratio sheet did not yield any ratios")
        ratio = per_part_ratio

    return as_of, horizon_end, remaining_days, parts, deliveries, ratio


def compute(as_of: date, horizon_end: date, remaining_days: int, parts: List[PartRow], deliveries: List[DeliveryRow], ratio: Union[float, Dict[str, float]]):
    # group deliveries by part
    by_part: Dict[str, List[DeliveryRow]] = {}
    for d in deliveries:
        by_part.setdefault(d.part_code, []).append(d)

    results = []
    for p in parts:
        part_code = p.part_code
        rate = p.daily_consumption_units
        current = p.current_units

        if rate > 0:
            current_doh = current / rate
            projected_stockout_date = as_of + timedelta(days=int(math.floor(current_doh)))
        else:
            current_doh = None
            projected_stockout_date = None

        ds = by_part.get(part_code, [])
        inbound_units_by_sep30 = sum(d.inbound_units for d in ds if d.inbound_date <= horizon_end)

        if rate > 0:
            delivered_doh_to_sep30 = (current + inbound_units_by_sep30) / rate
        else:
            delivered_doh_to_sep30 = None

        remaining_sept_demand_units = rate * remaining_days
        additional_units_needed = max(0.0, remaining_sept_demand_units - current - inbound_units_by_sep30)

        if isinstance(ratio, dict):
            units_per_crate = ratio.get(part_code)
            if units_per_crate is None:
                raise ValueError(f"Missing ratio for part {part_code}")
        else:
            units_per_crate = ratio

        if additional_units_needed > 0:
            raw_crates = additional_units_needed / units_per_crate
            # guard for float artifacts near integers
            crates_required = int(math.ceil(raw_crates - 1e-12))
            rounding_applied = abs(raw_crates - round(raw_crates)) > 1e-9
        else:
            raw_crates = 0.0
            crates_required = 0
            rounding_applied = False

        all_dates_for_part = [d.inbound_date for d in ds]
        earliest_scheduled = min(all_dates_for_part) if all_dates_for_part else None

        if crates_required == 0:
            required_delivery_date = None
        else:
            if projected_stockout_date is None:
                required_delivery_date = None
            else:
                if earliest_scheduled is not None and earliest_scheduled <= projected_stockout_date:
                    if delivered_doh_to_sep30 is None:
                        required_delivery_date = projected_stockout_date
                    else:
                        required_delivery_date = as_of + timedelta(days=int(math.floor(delivered_doh_to_sep30)))
                else:
                    required_delivery_date = projected_stockout_date

        if crates_required > 0 and (earliest_scheduled is None or (required_delivery_date is not None and required_delivery_date < earliest_scheduled)):
            earlier_delivery_required = True
        else:
            earlier_delivery_required = False

        results.append(
            {
                "Part_Code": part_code,
                "Current_Units": current,
                "Daily_Consumption_Units": rate,
                "Current_DOH": current_doh,
                "Projected_Stockout_Date": projected_stockout_date,
                "Inbound_Units_By_Sep30": inbound_units_by_sep30,
                "Delivered_DOH_To_Sep30": delivered_doh_to_sep30,
                "Remaining_September_Demand_Units": remaining_sept_demand_units,
                "Additional_Units_Needed": additional_units_needed,
                "Crates_Required_Rounded_Up": crates_required,
                "Required_Delivery_Date": required_delivery_date,
                "Rounding_Applied": rounding_applied,
                "Earlier_Delivery_Required": earlier_delivery_required,
                "Earliest_Scheduled_Delivery_Date": earliest_scheduled,
            }
        )

    return results


def _iso_or_none(d: Optional[date]) -> Optional[str]:
    return d.isoformat() if d is not None else None


def write_output(as_of: date, horizon_end: date, remaining_days: int, results: List[dict]):
    wb = openpyxl.Workbook()

    # remove default sheet
    default = wb.active
    wb.remove(default)

    ws1 = wb.create_sheet("Part_Results")
    ws2 = wb.create_sheet("Additional_Resupply_Needed")

    # Metadata
    ws1["A1"].value = "Field"
    ws1["B1"].value = "Value"

    ws1["A2"].value = "AsOfDate"
    ws1["B2"].value = as_of.isoformat()

    ws1["A3"].value = "PlanningHorizonEnd"
    ws1["B3"].value = horizon_end.isoformat()

    ws1["A4"].value = "RemainingDaysInSeptember"
    ws1["B4"].value = int(remaining_days)

    # Header row at 6
    headers = [
        "Part_Code",
        "Current_Units",
        "Daily_Consumption_Units",
        "Current_DOH",
        "Projected_Stockout_Date",
        "Inbound_Units_By_Sep30",
        "Delivered_DOH_To_Sep30",
        "Remaining_September_Demand_Units",
        "Additional_Units_Needed",
        "Crates_Required_Rounded_Up",
        "Required_Delivery_Date",
        "Rounding_Applied",
        "Earlier_Delivery_Required",
        "Earliest_Scheduled_Delivery_Date",
    ]

    for c, h in enumerate(headers, start=1):
        ws1.cell(6, c).value = h

    # Data rows start at 7
    r = 7
    for row in results:
        out = dict(row)
        out["Projected_Stockout_Date"] = _iso_or_none(out["Projected_Stockout_Date"])
        out["Required_Delivery_Date"] = _iso_or_none(out["Required_Delivery_Date"])
        out["Earliest_Scheduled_Delivery_Date"] = _iso_or_none(out["Earliest_Scheduled_Delivery_Date"])

        for c, h in enumerate(headers, start=1):
            v = out.get(h)
            if v is None:
                continue
            ws1.cell(r, c).value = v
        r += 1

    # Sheet 2
    headers2 = [
        "Part_Code",
        "Required_Delivery_Date",
        "Crates_Required_Rounded_Up",
        "Additional_Units_Needed",
        "Rounding_Applied",
        "Earlier_Delivery_Required",
    ]
    for c, h in enumerate(headers2, start=1):
        ws2.cell(1, c).value = h

    r2 = 2
    for row in results:
        if int(row["Crates_Required_Rounded_Up"]) <= 0:
            continue

        required_iso = _iso_or_none(row["Required_Delivery_Date"])

        values = {
            "Part_Code": row["Part_Code"],
            "Required_Delivery_Date": required_iso,
            "Crates_Required_Rounded_Up": int(row["Crates_Required_Rounded_Up"]),
            "Additional_Units_Needed": row["Additional_Units_Needed"],
            "Rounding_Applied": bool(row["Rounding_Applied"]),
            "Earlier_Delivery_Required": bool(row["Earlier_Delivery_Required"]),
        }

        for c, h in enumerate(headers2, start=1):
            v = values.get(h)
            if v is None:
                continue
            ws2.cell(r2, c).value = v
        r2 += 1

    wb.save(OUT_PATH)


def validate_output(expected_part_count: int):
    wb = openpyxl.load_workbook(OUT_PATH, data_only=False)

    print("\n=== OUTPUT VALIDATION ===")
    print("Sheet names:", wb.sheetnames)

    ws1 = wb["Part_Results"]
    ws2 = wb["Additional_Resupply_Needed"]

    # 1) metadata cells A1:B4
    print("\nPart_Results metadata A1:B4:")
    for r in range(1, 5):
        print(f"Row {r}:", [ws1.cell(r, 1).value, ws1.cell(r, 2).value])

    # 2) header row (row 6)
    header = [ws1.cell(6, c).value for c in range(1, 15)]
    print("\nPart_Results header row 6 (14 cols):", header)

    # 3) data rows: first 3 and last
    # Determine last data row by scanning col A from row 7
    last = 6
    for r in range(7, ws1.max_row + 1):
        if ws1.cell(r, 1).value is None:
            break
        last = r

    print("\nPart_Results first 3 data rows:")
    for r in range(7, min(10, last + 1)):
        row = [ws1.cell(r, c).value for c in range(1, 15)]
        print(f"Row {r}:", row)

    print("\nPart_Results last data row:")
    row = [ws1.cell(last, c).value for c in range(1, 15)]
    print(f"Row {last}:", row)

    data_count = max(0, last - 6)
    print("\nPart_Results data row count:", data_count)
    print("Expected part count:", expected_part_count)

    # Sheet 2: header and all rows
    print("\nAdditional_Resupply_Needed header:", [ws2.cell(1, c).value for c in range(1, 7)])
    print("Additional_Resupply_Needed rows:")
    for r in range(2, ws2.max_row + 1):
        row = [ws2.cell(r, c).value for c in range(1, 7)]
        if all(v is None for v in row):
            continue
        print(f"Row {r}:", row)

    # 7-9 type validations
    def is_iso_date_str(s: object) -> bool:
        if s is None:
            return True
        if not isinstance(s, str):
            return False
        try:
            datetime.strptime(s, "%Y-%m-%d")
            return True
        except ValueError:
            return False

    date_cols = {
        "Projected_Stockout_Date": 5,
        "Required_Delivery_Date": 11,
        "Earliest_Scheduled_Delivery_Date": 14,
    }
    bool_cols = {
        "Rounding_Applied": 12,
        "Earlier_Delivery_Required": 13,
    }

    problems = []

    if wb.sheetnames != ["Part_Results", "Additional_Resupply_Needed"]:
        problems.append(f"Sheet name mismatch: {wb.sheetnames}")

    expected_headers = [
        "Part_Code",
        "Current_Units",
        "Daily_Consumption_Units",
        "Current_DOH",
        "Projected_Stockout_Date",
        "Inbound_Units_By_Sep30",
        "Delivered_DOH_To_Sep30",
        "Remaining_September_Demand_Units",
        "Additional_Units_Needed",
        "Crates_Required_Rounded_Up",
        "Required_Delivery_Date",
        "Rounding_Applied",
        "Earlier_Delivery_Required",
        "Earliest_Scheduled_Delivery_Date",
    ]
    if header != expected_headers:
        problems.append("Part_Results header mismatch")

    if data_count != expected_part_count:
        problems.append(f"Part_Results data row count mismatch: {data_count} != {expected_part_count}")

    for r in range(7, last + 1):
        # date checks
        for name, c in date_cols.items():
            v = ws1.cell(r, c).value
            if not is_iso_date_str(v):
                problems.append(f"Row {r} column {name} not ISO date string: {v!r} ({type(v)})")
        # boolean checks
        for name, c in bool_cols.items():
            v = ws1.cell(r, c).value
            if v is None:
                continue
            if not isinstance(v, bool):
                problems.append(f"Row {r} column {name} not bool: {v!r} ({type(v)})")
        # numeric checks for known numeric columns
        numeric_cols = [2, 3, 4, 6, 7, 8, 9, 10]
        for c in numeric_cols:
            v = ws1.cell(r, c).value
            if v is None:
                continue
            if not isinstance(v, (int, float)):
                problems.append(f"Row {r} column {c} not numeric: {v!r} ({type(v)})")

    for r in range(2, ws2.max_row + 1):
        crates = ws2.cell(r, 3).value
        if crates is None:
            continue
        if not isinstance(crates, (int, float)) or crates <= 0:
            problems.append(f"Additional_Resupply_Needed row {r} has non-positive or non-numeric crates: {crates!r}")

        d = ws2.cell(r, 2).value
        if not is_iso_date_str(d):
            problems.append(f"Additional_Resupply_Needed row {r} date not ISO string: {d!r} ({type(d)})")

        for c in (5, 6):
            v = ws2.cell(r, c).value
            if v is None:
                continue
            if not isinstance(v, bool):
                problems.append(f"Additional_Resupply_Needed row {r} bool col {c} not bool: {v!r} ({type(v)})")

        for c in (4,):
            v = ws2.cell(r, c).value
            if v is None:
                continue
            if not isinstance(v, (int, float)):
                problems.append(f"Additional_Resupply_Needed row {r} numeric col {c} not numeric: {v!r} ({type(v)})")

    if problems:
        raise AssertionError("\n".join(problems))

    print("\nAll validation checks passed.")


def main():
    as_of, horizon_end, remaining_days, parts, deliveries, ratio = read_source()
    results = compute(as_of, horizon_end, remaining_days, parts, deliveries, ratio)
    write_output(as_of, horizon_end, remaining_days, results)
    validate_output(expected_part_count=len(parts))


if __name__ == "__main__":
